    // 应用配置
    public static class AppConfiguration
    {
        public static WebApplication CreateApp(string[] args)
        {
            var builder = WebApplication.CreateBuilder(args);

            // 配置服务
            builder.Services.AddHealthChecks()
                .AddCheck("self", () => HealthCheckResult.Healthy())
                .AddCheck("memory", () =>
                {
                    var allocated = GC.GetTotalMemory(false);
                    var threshold = 1024L * 1024L * 512L; // 512MB
                    return allocated < threshold
                        ? HealthCheckResult.Healthy()
                        : HealthCheckResult.Degraded($"内存使用: {allocated / 1024 / 1024}MB");
                });

            var app = builder.Build();

            // 配置中间件
            app.UseHealthChecks("/health", new HealthCheckOptions
            {
                ResponseWriter = async (context, report) =>
                {
                    context.Response.ContentType = "application/json";
                    var result = new
                    {
                        status = report.Status.ToString(),
                        checks = report.Entries.Select(e => new
                        {
                            name = e.Key,
                            status = e.Value.Status.ToString(),
                            description = e.Value.Description
                        })
                    };
                    await context.Response.WriteAsJsonAsync(result);
                }
            });

            app.MapGet("/", () => "Hello from Container!");

            return app;
        }
    }

    // GitHub Actions 示例
    /*
    name: Build and Deploy

    on:
      push:
        branches: [main]

    jobs:
      build:
        runs-on: ubuntu-latest
        steps:
        - uses: actions/checkout@v3

        - name: Setup .NET
          uses: actions/setup-dotnet@v3
          with:
            dotnet-version: '8.0.x'

        - name: Build and Test
          run: |
            dotnet restore
            dotnet build --no-restore
            dotnet test --no-build

        - name: Login to Docker Hub
          uses: docker/login-action@v2
          with:
            username: ${{ secrets.DOCKER_USERNAME }}
            password: ${{ secrets.DOCKER_PASSWORD }}

        - name: Build and push
          uses: docker/build-push-action@v4
          with:
            push: true
            tags: myuser/myapp:${{ github.sha }}
    */

    // Azure DevOps 示例
    /*
    trigger:
    - main

    pool:
      vmImage: 'ubuntu-latest'

    steps:
    - task: UseDotNet@2
      inputs:
        version: '8.0.x'

    - script: dotnet build --configuration Release
      displayName: Build

    - task: Docker@2
      inputs:
        containerRegistry: 'MyACR'
        repository: 'myapp'
        command: 'buildAndPush'
        Dockerfile: '**/Dockerfile'
        tags: |
          $(Build.BuildId)
          latest
    */

    // 环境变量配置示例
    public class EnvironmentConfig
    {
        public string Environment { get; set; }
        public string ConnectionString { get; set; }
        public string RedisConnection { get; set; }

        public static EnvironmentConfig Load()
        {
            return new EnvironmentConfig
            {
                Environment = Environment.GetEnvironmentVariable("ASPNETCORE_ENVIRONMENT") ?? "Development",
                ConnectionString = Environment.GetEnvironmentVariable("ConnectionStrings__DefaultConnection"),
                RedisConnection = Environment.GetEnvironmentVariable("Redis__Configuration")
            };
        }
    }
}
